import math

def count_up_to(n):
    if n <= 2:
        return []
    def is_prime(x):
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        limit = int(math.sqrt(x))
        for d in range(3, limit + 1, 2):
            if x % d == 0:
                return False
        return True

    return [i for i in range(2, n) if is_prime(i)]
