def count_up_to(n):
    def is_prime(p):
        if p < 2:
            return False
        for i in range(2, int(p ** 0.5) + 1):
            if p % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)
    return primes
