def is_nested(string):
    """
    Returns True if the string contains a valid nested bracket subsequence,
    i.e., there exist indices i<j<k<l with s[i]='[', s[j]='[', s[k]=']', s[l]=']'.
    """
    n = len(string)
    for i in range(n):
        if string[i] != '[':
            continue
        for j in range(i + 1, n):
            if string[j] == '[':
                for k in range(j + 1, n):
                    if string[k] == ']':
                        for l in range(k + 1, n):
                            if string[l] == ']':
                                return True
    return False
```

